        question: "Can I cram Mathematics in the final month before JEE?",
        answer: "Not effectively — Mathematics problems compound ideas across chapters, so a weak earlier foundation limits how much a late cramming push can achieve. Steady, cumulative practice throughout preparation works far better.",
